/**
 * Milestone rows for a project: identity, open/closed state, and progress
 * counted over the project's live issues.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, count, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type { CreateMilestoneInput, UpdateMilestoneInput } from "@/schemas/milestone";
import type { IsoTimestamp, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)))
    .get();
  return row ? toMilestone(row) : null;
}

export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId)),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** True when another milestone in the project already uses this name. */
export async function milestoneNameTaken(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId?: MilestoneId,
): Promise<boolean> {
  const key = milestoneNameKey(name);
  const rows = getDb()
    .select({ id: milestones.id, name: milestones.name })
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId)),
    )
    .all();
  return rows.some(
    (row) => row.id !== exceptId && milestoneNameKey(row.name) === key,
  );
}

export async function insertMilestone(
  input: CreateMilestoneInput,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  input: UpdateMilestoneInput,
): Promise<Milestone | null> {
  const current = await findMilestoneById(input.orgId, input.milestoneId);
  if (!current) return null;

  const row = getDb()
    .update(milestones)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, input.orgId),
        eq(milestones.id, input.milestoneId),
      ),
    )
    .returning()
    .get();
  return row ? toMilestone(row) : null;
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone | null> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)))
    .returning()
    .get();
  return row ? toMilestone(row) : null;
}

/**
 * Live-issue progress for every milestone of a project. Milestones with no
 * live issues are absent from the map; callers treat that as zeros.
 */
export async function progressForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ReadonlyMap<string, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const byMilestone = new Map<string, { open: number; closed: number }>();
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const bucket = byMilestone.get(row.milestoneId) ?? { open: 0, closed: 0 };
    if ((CLOSED_ISSUE_STATUSES as readonly string[]).includes(row.status)) {
      bucket.closed += row.value;
    } else {
      bucket.open += row.value;
    }
    byMilestone.set(row.milestoneId, bucket);
  }

  const progress = new Map<string, MilestoneProgress>();
  for (const [id, bucket] of byMilestone) {
    progress.set(id, {
      total: bucket.open + bucket.closed,
      open: bucket.open,
      closed: bucket.closed,
    });
  }
  return progress;
}

export function progressOrEmpty(
  progress: ReadonlyMap<string, MilestoneProgress>,
  milestoneId: MilestoneId,
): MilestoneProgress {
  return progress.get(milestoneId) ?? EMPTY_PROGRESS;
}

export async function setIssueMilestone(
  orgId: OrgId,
  issueId: IssueId,
  milestoneId: MilestoneId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ milestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/**
 * Moves the milestone's open live issues. Closed and archived issues stay.
 * Returns the ids that moved.
 */
export async function moveOpenLiveIssues(
  orgId: OrgId,
  fromMilestoneId: MilestoneId,
  toMilestoneId: MilestoneId | null,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.milestoneId, fromMilestoneId),
        isNull(issues.archivedAt),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
      ),
    )
    .all();

  const ids = rows.map((row) => row.id as IssueId);
  if (ids.length === 0) return [];

  getDb()
    .update(issues)
    .set({ milestoneId: toMilestoneId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...ids])))
    .run();

  return ids;
}

