/**
 * Milestone lifecycle for a project: naming, the open-milestone cap, closing
 * (which moves open live issues) and progress.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { toIsoTimestamp } from "@/types/common";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { IssueId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const project = await liveEditableProject(actor, input.orgId, input.projectId);

  if (await milestoneRepo.milestoneNameTaken(input.orgId, project.id, input.name)) {
    throw new MilestoneStateError("name_taken");
  }
  await assertOpenCapacity(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone(input);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await liveEditableProject(actor, input.orgId, milestone.projectId);

  if (
    input.name !== undefined &&
    (await milestoneRepo.milestoneNameTaken(
      input.orgId,
      milestone.projectId,
      input.name,
      milestone.id,
    ))
  ) {
    throw new MilestoneStateError("name_taken");
  }

  return requireFound(
    await milestoneRepo.updateMilestone(input),
    "Milestone",
    input.milestoneId,
  );
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await liveEditableProject(actor, input.orgId, milestone.projectId);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const targetId = await resolveCloseTarget(input.orgId, milestone, input.moveOpenIssuesTo);

  const movedIssueIds = await issueRepo.moveOpenLiveIssues(
    input.orgId,
    milestone.id,
    targetId,
  );
  const closed = requireFound(
    await milestoneRepo.setMilestoneClosedAt(
      input.orgId,
      milestone.id,
      toIsoTimestamp(new Date()),
    ),
    "Milestone",
    milestone.id,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  await liveEditableProject(actor, orgId, milestone.projectId);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }
  await assertOpenCapacity(orgId, milestone.projectId);

  const reopened = requireFound(
    await milestoneRepo.setMilestoneClosedAt(orgId, milestoneId, null),
    "Milestone",
    milestoneId,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const progress = await milestoneRepo.progressForProject(orgId, projectId);
  const now = new Date();

  return [...milestones]
    .sort(compareMilestones)
    .map((milestone) =>
      withProgress(milestone, milestoneRepo.progressOrEmpty(progress, milestone.id), now),
    );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.progressForProject(orgId, milestone.projectId);
  return withProgress(
    milestone,
    milestoneRepo.progressOrEmpty(progress, milestone.id),
    new Date(),
  );
}

/** Project must exist, be in scope, be editable, and not be archived. */
async function liveEditableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
) {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

async function assertOpenCapacity(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

async function resolveCloseTarget(
  orgId: OrgId,
  milestone: Milestone,
  targetId: MilestoneId | null,
): Promise<MilestoneId | null> {
  if (targetId === null) return null;
  if (targetId === milestone.id) {
    throw new NotFoundError("Milestone", targetId);
  }

  const target = await milestoneRepo.findMilestoneById(orgId, targetId);
  if (target === null || target.projectId !== milestone.projectId) {
    throw new NotFoundError("Milestone", targetId);
  }
  if (target.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
  return target.id;
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isOverdue(milestone, progress, now),
  };
}

function isOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): boolean {
  if (milestone.closedAt !== null) return false;
  if (milestone.targetDate === null) return false;
  if (progress.open === 0) return false;
  return new Date(milestone.targetDate).getTime() < now.getTime();
}

/** Open milestones first; earliest target date first; undated last; then oldest. */
function compareMilestones(a: Milestone, b: Milestone): number {
  const aClosed = a.closedAt === null ? 0 : 1;
  const bClosed = b.closedAt === null ? 0 : 1;
  if (aClosed !== bClosed) return aClosed - bClosed;

  if (a.targetDate === null && b.targetDate !== null) return 1;
  if (a.targetDate !== null && b.targetDate === null) return -1;
  if (a.targetDate !== null && b.targetDate !== null && a.targetDate !== b.targetDate) {
    return a.targetDate < b.targetDate ? -1 : 1;
  }

  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return 0;
}

