{"type":"SearchReplace","EditsApplied":{"old_string":"export async function getIssue(","new_string":"/**
 * Puts an issue in an open milestone of its own project, moves it, or clears
 * the assignment. A refusal leaves the issue where it was.
 */
export async function setIssueMilestone(
  actor: Actor,
  input: SetIssueMilestoneInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  assertNotArchived("Project", project.id, project);
  await assertOpenMilestone(input.orgId, issue.projectId, input.milestoneId);

  return issueRepo.setIssueMilestone(input.orgId, issue.id, input.milestoneId);
}

async function assertOpenMilestone(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: Issue["milestoneId"],
): Promise<void> {
  if (milestoneId === null) return;

  const milestone = await milestoneRepo.findMilestoneById(orgId, milestoneId);
  if (milestone === null || milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
}

